function ActionDarkDreamLevelDetails:InitToggleData()
    self.togglesData = {}
    for i, v in pairs(Config) do
        table.insert(self.togglesData, {
            text = v.text,
            func = Bind(self, self.TopTabOnClickHandler),
            type = v.type,
            index = v.index,
            interface = v.interface,
            isLock = self:GetIsLock(v.type,v.index),
            lockDes = localize("请先通关前置关卡"),
            isNeedPlay = self:IsNeedPlayUnLockAni(v.type,v.index),
            aniName = "ActionDarkDreamLevelDetails_CellUnlock",
            checkFunc = function(index)
                local checkData = self.togglesData[index]
                if checkData.isLock then
                    GameUtils.Toast(checkData.lockDes)
                    return false
                end
                return true
            end,
        })
    end
    CfUtils.CookieSave("ActionDarkDreamLevelDetails_QuestId",nil)
    ChaoticRecallUtils.GetChaoticRecallMgr():CleanCurData()
end

function ActionDarkDreamLevelDetails:GetIsLock(type,index)
    if isNull(self.nodeVo.hardLevels) then
       return false
    end

    if type == HardType.Normal then
        return false
    elseif type == HardType.Hard then
        if index == 1 then
            return checkNumber(self.data.passed) == 0
        else
            return checkNumber(self.data.hardPassed[index - 1]) == 0
        end
    end
    return false
end

function ActionDarkDreamLevelDetails:TopTabOnClickHandler(index)
    if not isNull(self.index) and self.index == index then
        return
    end
    self.index = index

    self.hardIndex = self.togglesData[self.index].index

    self:RefreshLevelShow()
end

function ActionDarkDreamLevelDetails:InitNodeEnv()
    if self.CommonTabToggleUp then
        ---@type CommonTabToggleUp
        local env = CfUtils.GetLuaScr(self.CommonTabToggleUp, "Game.Behaviours.CommonTabToggleUp")
        if not isNull(env) then
            self.commonTabEnv = env
            local index = self:GetInitIndex()
            self.commonTabEnv:FillToggles(self.togglesData,index)
        end
    end
end

function ActionDarkDreamLevelDetails:Awake()
    SetButtonAction(self.BtnEnter.gameObject,Bind(self,self.OnBtnEnterClick))
    self.parameters = self.controller.Argument.parameters
    if not isNull(self.parameters.data) then
        self.data = self.parameters.data
        self.groupId = checkNumber(self.parameters.groupId)
        local nodeVo = ChaoticRecallUtils.GetChaoticRecallNodeVo(self.data.id)
        if not isNull(nodeVo) then
            self.nodeVo = nodeVo
            local index = self:GetInitIndex()
            self:InitHardNode()
            self:SetTitleAndTime()
            self:TopTabOnClickHandler(index)
            if not isNull(self.nodeVo.hardLevels) then
                KTool.SetActive(self.CommonTabToggleUp.gameObject,true)
            else
                KTool.SetActive(self.CommonTabToggleUp.gameObject,false)
            end
        end
        self:InitBg()
    end
end

function ActionDarkDreamLevelDetails:GetInitIndex()
    if isNull(self.nodeVo.hardLevels) then
        return 1
    else
        if self.data.hardPassed[1] == 1 then
            return 3
        elseif self.data.isPass == 1 then
            return 2
        end
    end
    return 1
end

function ActionDarkDreamLevelDetails:IsNeedPlayUnLockAni(type,index)
    if not isNull(self.nodeVo.hardLevels) then
        local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
        local passedQuestId = ChaoticRecallUtils.GetChaoticRecallMgr():GetCurQuestId()
        if checkNumber(passedQuestId) > 0  then
            local questId = CfUtils.CookieLoad("ActionDarkDreamLevelDetails_QuestId")
            if checkNumber(questId) > 0 then
                if questId == passedQuestId then
                    local needId = checkNumber(self:GetNeedJudgeId(type,index))
                    if needId > 0 and  needId == checkNumber(passedQuestId) then
                        return true
                    end
                end
            end
        end
    end
    return false
end

function ActionDarkDreamLevelDetails:GetNeedJudgeId(type,index)
    if isNull(self.nodeVo.hardLevels) then
        return 0
    end

    if type == HardType.Normal then
        return 0
    elseif type == HardType.Hard then
        if index == 1 then
            return checkNumber(self.data.id)
        else
            return checkNumber(self.nodeVo.hardLevels[index])
        end
    end
    return false
end

