function ActionDarkDreamLevelDetails:InitStarList()
    if self:IsHardLevel() then
        KTool.SetActive(self.LevelObjectivesNode.gameObject,false)
        return
    end
    KTool.SetActive(self.LevelObjectivesNode.gameObject,true)
    self.starEnv = {}
    if not isNull(self.Cell) then
        local env = CfUtils.GetLuaScr(self.Cell,StarConditionCellPath)
        if not isNull(env) then
           table.insert(self.starEnv,env)
        end
    end
    
    if isNotNull(self.nodeVo.starCondition) and table.count(self.nodeVo.starCondition) > 0 then
        for i, v in ipairs(self.nodeVo.starCondition) do
            local conditionVo = checkTable(CfUtils.GetCfVo(AutoIds.IdSetting820, "QuestConditionVo", v))
            if i > 1 then
                if conditionVo then
                    local cellGo = CS.UnityEngine.GameObject.Instantiate(self.Cell.gameObject)
                    if not isNull(cellGo) then
                        KTool.SetParent(cellGo,self.ObjectivesList.gameObject,false)
                        local cellEnv = CfUtils.GetLuaScr(cellGo,StarConditionCellPath)
                        if not isNull(cellEnv) then
                            local isComplete = self:IsComplete(i)
                            cellEnv:RefreshConditionShow(conditionVo,self.nodeVo,isComplete,i)
                            table.insert(self.starEnv,cellEnv)
                        end
                    end
                end
            else
                if conditionVo then
                    local isComplete = self:IsComplete(i)
                    self.starEnv[i]:RefreshConditionShow(conditionVo,self.nodeVo,isComplete,i)
                end
            end
        end
    else
        CfUtils.SetActive(self.LevelObjectivesNode.gameObject,false)
    end
end

function ActionDarkDreamLevelDetails:IsComplete(index)
    for i, v in ipairs(self.data.starCompleted) do
        if v == index then
            return true
        end
    end
    return false
end

