function ActionDarkDreamLevelDetails:OnBtnEnterClick()
    local levelList = self:IsHardLevel() and self.nodeVo.hardLevels[self.hardIndex] or self.nodeVo.levelList
    ---@type TeamComponent
    local teamComponent        = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
    local isCanEnter = true
    for i, v in pairs(self.nodeVo.levelList) do
        local t = teamComponent:GetTeamByQuestId(v, i)
        if not t then
            isCanEnter = false
            break
        end
        local count = teamComponent:GetTeamMemberCount(t)
        if count < 1 then
            isCanEnter = false
            break
        end
    end

    if isCanEnter then
        local questId = levelList[1]
        if not isNull(questId) then
            local teamComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
            teamComponent:SetTeamReq(checkNumber(questId), function()
                self:SaveData(questId)
                FightPreWarMgr:GetInstance():FightEnter(questId,{nodeId = self.nodeVo.id, groupId = self.nodeVo.groupId ,levelList = levelList, index = 1,hardType = self:GetHardType()},{{id = Constants.UITypeIds.ActionDarkDreamLevelDetails },})
            end)
        else

        end
    else
        GameUtils.Toast(localize("队伍不能为空"))
    end
end

function ActionDarkDreamLevelDetails:SaveData(questId)
    local isPass = self:IsHardLevel() and self.data.hardPassed[self.hardIndex]  or checkNumber(self.data.passed) == 1
    if not isPass then
        CfUtils.CookieSave("ActionDarkDreamLevelDetails_QuestId",questId)
    end
end

function ActionDarkDreamLevelDetails:GetHardType()
    if self:IsHardLevel() then
        return self.hardIndex
    end
    return 0
end

function ActionDarkDreamLevelDetails:InitRewards()
    local isHardLevel = self:IsHardLevel()
    local rewards = isHardLevel and self.nodeVo.hardRewards[self.hardIndex] or self.nodeVo.rewards
    if table.count(rewards) > 0 then
        local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsListLight")
        if scr then
            scr:FreshBaseUI(rewards)
            local isDraw = false
            if isHardLevel then
                isDraw = checkNumber(self.data.hardPassed[self.hardIndex]) == 1
            else
                isDraw = checkNumber(self.data.passed) == 1
            end
            scr:SetIsGetMaskShow(isDraw)
        end
    end
end

function ActionDarkDreamLevelDetails:IsHardLevel()
    if not isNull(self.nodeVo.hardLevels) then
        local toggleData = self.togglesData[self.index]
        if not isNull(toggleData) then
            return toggleData.type == HardType.Hard
        end
    end
    return  false
end

function ActionDarkDreamLevelDetails:InitTaskList()
    self.taskEnv = {}
    local levelList = self:IsHardLevel() and self.nodeVo.hardLevels[self.hardIndex] or self.nodeVo.levelList
    for i = 1, LevelListCount do
        local questId = levelList[i]
        local teamQuestId = self.nodeVo.levelList[i]
        local item = self["TaskList"..i]
        if not isNull(questId) then
            KTool.SetActive(item.gameObject,true)
            local env = CfUtils.GetLuaScr(item,"Game.UI.FightReady.ChaoticRecall.ActionDarkDreamLevelDetailsLevelNode")
            if env then
                env:RefreshShow(self.data,questId,i,teamQuestId,self.nodeVo.groupId)
                table.insert(self.taskEnv,env)
            end
        else
            KTool.SetActive(item.gameObject,false)
        end
    end
end

function ActionDarkDreamLevelDetails:OnFocus(focus)
    if focus then
        if not isNull(self.nodeVo) then
            self:RefreshTaskEnv()
        end
    end
end

function ActionDarkDreamLevelDetails:RefreshTaskEnv()
    if not isNull(self.taskEnv) then
        for i, v in pairs(self.taskEnv) do
            v:RefreshTeamInfo()
        end
    end
end

